            replacements.push({
              fileName: file.name,
              fileId: existingFileId,
              parentId: folderId,
              encryptedData: {
                cid: ipfsResult.cid,
                wrappedKey: encrypted.wrappedKey,
                iv: encrypted.iv,
                size: file.size,
                encryptionMode: encrypted.encryptionMode,
