/**
 * Upload Styles - Terminal Aesthetic
 *
 * Upload zone (drag-drop) and upload modal progress
 * Green accents, terminal feel
 */

/* ==========================================================================
   Upload Zone
   ========================================================================== */

.upload-zone-wrapper {
  width: 100%;
}

.upload-zone {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 120px;
  padding: var(--spacing-lg);
  border: var(--border-thickness) dashed var(--color-border);
  border-radius: 0;
  background-color: var(--color-background);
  cursor: pointer;
  transition: border-color 0.15s ease, background-color 0.15s ease;
}

.upload-zone:hover {
  border-color: var(--color-green-primary);
  background-color: var(--color-green-darker);
}

.upload-zone:focus-within {
  outline: 2px solid var(--color-green-primary);
  outline-offset: 2px;
}

/* Active drop state */
.upload-zone-active {
  border-color: var(--color-green-primary);
  border-style: solid;
  background-color: var(--color-green-darker);
  box-shadow: var(--glow-green);
}

/* Uploading state */
.upload-zone-uploading {
  cursor: default;
  opacity: 0.7;
}

/* Content */
.upload-zone-content {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--spacing-xs);
  text-align: center;
  color: var(--color-text-secondary);
}

.upload-zone-icon {
  font-size: 2rem;
  line-height: 1;
  color: var(--color-text-secondary);
}

.upload-zone-text {
  margin: 0;
  font-family: var(--font-family-mono);
  font-size: var(--font-size-sm);
  color: var(--color-text-primary);
}

/* Error message */
.upload-zone-error {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--spacing-xs);
  margin-top: var(--spacing-xs);
  padding: var(--spacing-sm);
  font-family: var(--font-family-mono);
  font-size: var(--font-size-xs);
  color: var(--color-error);
  background-color: var(--color-error-dim);
  border: var(--border-thickness) solid var(--color-error);
  border-radius: 0;
}

.upload-zone-error-dismiss {
  padding: 0;
  font-size: 1rem;
  font-weight: var(--font-weight-normal);
  line-height: 1;
  color: inherit;
  cursor: pointer;
  background: transparent;
  border: none;
  opacity: 0.7;
}

.upload-zone-error-dismiss:hover {
  opacity: 1;
}

/* ==========================================================================
   Inline Upload Progress (replaces popup widget)
   ========================================================================== */

/* Upload row matches .file-list-item grid -- no extra cursor (not clickable) */
.upload-inline-row {
  cursor: default;
}

.upload-inline-row:hover {
  background-color: var(--color-green-darker);
}

/* Completion flash */
.upload-inline-row--complete {
  background-color: rgb(0 208 132 / 8%);
}

/* Error row background */
.upload-inline-row--error {
  background-color: var(--color-error-dim);
}

/* Icon color overrides */
.upload-inline-icon {
  color: var(--color-green-dim);
}

.upload-inline-row--error .upload-inline-icon {
  color: var(--color-error);
}

/* Name wrapper -- stacks name and progress bar vertically */
.upload-inline-name-wrapper {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
  flex: 1;
}

/* Progress bar track */
.upload-inline-progress-track {
  height: 3px;
  background-color: var(--color-border-dim);
  overflow: hidden;
  width: 100%;
}

/* Progress bar fill */
.upload-inline-progress-fill {
  height: 100%;
  background-color: var(--color-green-primary);
  transition: width 0.2s ease;
}

.upload-inline-progress-fill[data-status='complete'] {
  background-color: var(--color-green-primary);
}

.upload-inline-progress-fill[data-status='error'] {
  background-color: var(--color-error);
}

/* Encrypting pulse animation */
@keyframes upload-inline-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.4;
  }
}

.upload-inline-progress-track--pulse .upload-inline-progress-fill {
  width: 100% !important;
  animation: upload-inline-pulse 1.5s ease-in-out infinite;
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .upload-inline-progress-fill,
  .upload-inline-progress-track--pulse .upload-inline-progress-fill {
    animation: none;
    transition: none;
  }
}

/* Action buttons container -- aligns buttons to the right within the date column */
.upload-inline-actions {
  display: flex;
  gap: var(--spacing-xs);
  align-items: center;
  justify-content: flex-end;
}

/* Action buttons */
.upload-inline-btn {
  padding: 2px var(--spacing-xs);
  font-family: var(--font-family-mono);
  font-size: var(--font-size-xs);
  color: var(--color-text-secondary);
  background: transparent;
  border: none;
  cursor: pointer;
  transition: color 0.15s ease;
}

.upload-inline-btn:hover {
  color: var(--color-text-primary);
}

.upload-inline-btn:focus-visible {
  outline: 1px solid var(--color-green-primary);
  outline-offset: 1px;
}

/* Retry button -- green accent */
.upload-inline-btn--retry {
  color: var(--color-green-primary);
}

.upload-inline-btn--retry:hover {
  box-shadow: var(--glow-green);
}

.upload-inline-btn--retry:focus-visible {
  outline: 1px solid var(--color-green-primary);
  outline-offset: 1px;
}

